import subprocess, re
files=['README.md','ROUTER.md','SKILL.md','assets/prompt-quality-card.md','assets/prompt-templates.md','references/agent-delegation.md','references/cli-reference.md','references/cloud-handoff.md','references/devin-tools.md','references/integration-patterns.md','references/providers-and-models.md']
base='.skilled/skills/cli-external-orchestration/cli-devin/'
def intro(text):
    lines=text.splitlines()
    # skip frontmatter
    if lines and lines[0]=='---':
        try: end=lines.index('---',1)
        except ValueError: end=0
        lines=lines[end+1:]
    # find H1
    i=next(i for i,l in enumerate(lines) if l.startswith('# '))
    j=i+1
    block=[]
    while j<len(lines) and not lines[j].startswith('---'):
        block.append(lines[j]); j+=1
    return '\n'.join(block).strip()
for f in files:
    cur=open(base+f).read()
    head=subprocess.check_output(['git','show',f'HEAD:{base}{f}'],text=True)
    a,b=intro(head),intro(cur)
    if a!=b:
        print('CHANGED INTRO',f); print('HEAD:',repr(a[:400])); print('CUR :',repr(b[:400]))
PY"}

